"""Sync voice lines generated by VVE_Builder into the classic PST install GemRB uses.

Safe to run any time, as often as you like: each run makes the game match what
VVE_Builder has generated right now.

  * Reads <vve>/pst_revoice/plan.csv (strref -> sound resref) and takes the audio from
    the first audio folder that has it (default: audio_fish, then audio_omnivoice, then audio).
    Production TTS is Fish Audio Drama 3; OmniVoice is kept as a fallback. Info-point
    examine lines use the same plan rows (Speaker=Narrator, VV<strref>); dump them with
    tools/vve_infopoints.py.
  * Copies new/changed WAVs into <game>/override; removes ones it put there earlier
    that are no longer generated.
  * In Dialog.tlk and dialogF.tlk it changes only the sound resref (flag + VV<strref>),
    never the text (keeps Fixpack/UB fixes), and only when the plan's text still
    matches the installed line. Empty original sound slots get the new resref; lines
    that already have original voice acting keep it.
  * "restore" rows of the plan (original voice acting) are applied as-is.
  * First run backs the tlk files up to <game>/vve_voices_backup; --uninstall puts
    everything back.

Usage:
  python tools/sync_vve_voices.py [--dry-run] [--vve D:/VVE_Builder-main] [--game C:/Program Files (x86)/Black Isle/Torment]
                                  [--audio-dir audio_fish --audio-dir audio_omnivoice --audio-dir audio]
  python tools/sync_vve_voices.py --uninstall
"""

import argparse
import csv
import difflib
import filecmp
import json
import os
import re
import shutil
import struct
import sys

TLKS = ["Dialog.tlk", "dialogF.tlk"]
STATE_DIR = "vve_voices_backup"
DEFAULT_AUDIO_DIRS = ["audio_fish", "audio_omnivoice", "audio"]
HEADER = 18
ENTRY = 26


def norm(s):
	return re.sub(r"[^a-z0-9]", "", s.lower())


def similar(a, b):
	a, b = norm(a), norm(b)
	if a == b:
		return 1.0
	if not a or not b:
		return 0.0
	sm = difflib.SequenceMatcher(None, a, b, autojunk=False)
	if sm.real_quick_ratio() < 0.6 or sm.quick_ratio() < 0.6:
		return 0.0
	# EE/classic differ in trailing tutorial notes: accept when most of the shorter text matches
	covered = sum(blk.size for blk in sm.get_matching_blocks()) / min(len(a), len(b))
	return max(sm.ratio(), covered - 0.1)


class Tlk:
	def __init__(self, path):
		self.path = path
		self.data = bytearray(open(path, "rb").read())
		sig, _lang, self.count, self.offset = struct.unpack_from("<8sHII", self.data, 0)
		if sig != b"TLK V1  ":
			raise SystemExit(f"{path}: not a TLK V1 file")

	def entry(self, ref):
		flags, sound, _v, _p, off, length = struct.unpack_from("<H8sIIII", self.data, HEADER + ENTRY * ref)
		text = bytes(self.data[self.offset + off:self.offset + off + length]).decode("cp1252", "replace")
		return flags, sound.rstrip(b"\0").decode("latin1"), text

	def raw(self, ref):
		pos = HEADER + ENTRY * ref
		return bytes(self.data[pos:pos + 10])  # flags + sound resref

	def put_raw(self, ref, raw):
		pos = HEADER + ENTRY * ref
		self.data[pos:pos + 10] = raw

	def set_sound(self, ref, sound):
		pos = HEADER + ENTRY * ref
		flags = struct.unpack_from("<H", self.data, pos)[0] | 2
		struct.pack_into("<H8s", self.data, pos, flags, sound.upper().encode("latin1")[:8].ljust(8, b"\0"))

	def save(self):
		tmp = self.path + ".tmp"
		with open(tmp, "wb") as f:
			f.write(self.data)
		os.replace(tmp, self.path)


def load_state(sdir):
	path = os.path.join(sdir, "state.json")
	if os.path.exists(path):
		return json.load(open(path))
	return {"files": {}, "strings": {}}


def save_state(sdir, state):
	tmp = os.path.join(sdir, "state.json.tmp")
	json.dump(state, open(tmp, "w"), indent=0)
	os.replace(tmp, os.path.join(sdir, "state.json"))


def pristine(sdir, game):
	"""Original tlk files (backed up on the first run)."""
	out = []
	for name in TLKS:
		live = os.path.join(game, name)
		if not os.path.exists(live):
			continue
		bak = os.path.join(sdir, name)
		if not os.path.exists(bak):
			shutil.copy2(live, bak)
		out.append((Tlk(live), Tlk(bak)))
	return out


def uninstall(game):
	sdir = os.path.join(game, STATE_DIR)
	if not os.path.isdir(sdir):
		raise SystemExit("Nothing to uninstall: no VVE voices synced into " + game)
	state = load_state(sdir)
	removed = 0
	for name in state["files"]:
		p = os.path.join(game, "override", name)
		if os.path.exists(p):
			os.remove(p)
			removed += 1
	saved = os.path.join(sdir, "override")
	if os.path.isdir(saved):
		for f in os.listdir(saved):
			shutil.copy2(os.path.join(saved, f), os.path.join(game, "override", f))
	for name in TLKS:
		bak = os.path.join(sdir, name)
		if os.path.exists(bak):
			shutil.copy2(bak, os.path.join(game, name))
	shutil.rmtree(sdir)
	print(f"Uninstalled: restored {', '.join(TLKS)}, removed {removed} voice files")


def vve_dir(vve):
	"""VVE_Builder output folder: pst_revoice (current name), else the old pst_overlay."""
	for name in ("pst_revoice", "pst_overlay"):
		if os.path.isdir(os.path.join(vve, name)):
			return os.path.join(vve, name)
	return os.path.join(vve, "pst_revoice")


def read_plan(vve):
	path = os.path.join(vve_dir(vve), "plan.csv")
	if not os.path.exists(path):
		raise SystemExit(f"No plan at {path}: run 'python pst_revoice.py plan' in VVE_Builder first")
	with open(path, encoding="utf-8-sig", newline="") as f:
		return list(csv.DictReader(f))


def main():
	ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
	ap.add_argument("--vve", default=r"D:\VVE_Builder-main")
	ap.add_argument("--game", default=r"C:\Program Files (x86)\Black Isle\Torment")
	ap.add_argument("--audio-dir", action="append",
	                help="audio folder under <vve>/pst_revoice, in priority order (default: audio_fish, audio_omnivoice, audio)")
	ap.add_argument("--min-match", type=float, default=0.75, help="text similarity needed to voice a line")
	ap.add_argument("--dry-run", action="store_true", help="report what would change, touch nothing")
	ap.add_argument("--uninstall", action="store_true")
	args = ap.parse_args()

	game = args.game
	if args.uninstall:
		return uninstall(game)

	audio_dirs = [os.path.join(vve_dir(args.vve), d) for d in (args.audio_dir or DEFAULT_AUDIO_DIRS)]
	audio_dirs = [d for d in audio_dirs if os.path.isdir(d)]
	available = {}
	for d in reversed(audio_dirs):  # earlier folders win
		for f in os.listdir(d):
			stem, ext = os.path.splitext(f)
			if ext.lower() in (".wav", ".ogg"):
				available[stem.upper()] = os.path.join(d, f)

	sdir = os.path.join(game, STATE_DIR)
	if not args.dry_run:
		os.makedirs(sdir, exist_ok=True)
	state = load_state(sdir)
	ours = set(state["files"])  # override files we installed earlier
	if args.dry_run and not os.path.isdir(sdir):
		tlks = [(Tlk(os.path.join(game, n)), Tlk(os.path.join(game, n))) for n in TLKS if os.path.exists(os.path.join(game, n))]
	else:
		tlks = pristine(sdir, game)
	orig = tlks[0][1]

	# what each strref should point at
	want = {}  # strref -> resref
	files = {}  # override file name -> source path
	stats = dict(generated=0, restored=0, no_audio=0, voiced=0, text=0, oob=0)
	mismatches = []
	for row in read_plan(args.vve):
		ref, resref, action = int(row["StrRef"]), row["SoundResRef"].strip().upper(), row["Action"].strip()
		if ref >= orig.count:
			stats["oob"] += 1
			continue
		_flags, cur, text = orig.entry(ref)
		if action == "restore":
			if cur.upper() != resref and similar(text, row["Text"]) >= args.min_match:
				want[ref] = resref
			stats["restored"] += 1
			continue
		if resref not in available:
			stats["no_audio"] += 1
			continue
		if cur:  # original voice acting stays
			stats["voiced"] += 1
			continue
		if similar(text, row["Text"]) < args.min_match:
			stats["text"] += 1
			mismatches.append((ref, text, row["Text"]))
			continue
		want[ref] = resref
		src = available[resref]
		files[resref + os.path.splitext(src)[1].upper()] = src
		stats["generated"] += 1

	override = os.path.join(game, "override")
	to_copy = []
	identical = []  # already in override byte for byte: just record them
	for name, src in files.items():
		dst = os.path.join(override, name)
		st = os.stat(src)
		if name in ours and state["files"][name] == [st.st_size, int(st.st_mtime)] and os.path.exists(dst):
			continue
		if os.path.exists(dst) and os.path.getsize(dst) == st.st_size and filecmp.cmp(src, dst, shallow=False):
			identical.append((name, st))
			continue
		to_copy.append((name, src, st))
	to_remove = sorted(ours - set(files))
	clashes = [n for n, _s, _st in to_copy if n not in ours and os.path.exists(os.path.join(override, n))]
	old_refs = {int(k) for k in state["strings"]}
	changed_refs = {r for r in want if state["strings"].get(str(r)) != want[r]} | (old_refs - set(want))

	print(f"VVE plan: {stats['generated']} lines with audio, {stats['restored']} restore rows, "
	      f"{stats['no_audio']} not generated yet, {stats['voiced']} already voiced (kept), "
	      f"{stats['text']} text mismatch, {stats['oob']} out of range")
	print(f"Changes: copy {len(to_copy)} files ({len(identical)} identical skipped), remove {len(to_remove)}, update {len(changed_refs)} strings")
	for ref, a, b in mismatches[:5]:
		print(f"  text mismatch {ref}: game={a[:60]!r} plan={b[:60]!r}")
	if args.dry_run:
		print("(dry run, nothing changed)")
		return

	if clashes:
		os.makedirs(os.path.join(sdir, "override"), exist_ok=True)
		for n in clashes:
			shutil.copy2(os.path.join(override, n), os.path.join(sdir, "override", n))
	for name, st in identical:
		state["files"][name] = [st.st_size, int(st.st_mtime)]
	for name, src, st in to_copy:
		shutil.copyfile(src, os.path.join(override, name))
		state["files"][name] = [st.st_size, int(st.st_mtime)]
	for name in to_remove:
		p = os.path.join(override, name)
		if os.path.exists(p):
			os.remove(p)
		saved = os.path.join(sdir, "override", name)
		if os.path.exists(saved):
			shutil.copy2(saved, p)
		del state["files"][name]

	# rebuild the sound fields from the originals, so dropped lines go back to silent
	for live, bak in tlks:
		for ref in old_refs - set(want):
			if ref < live.count:
				live.put_raw(ref, bak.raw(ref))
		for ref, resref in want.items():
			if ref < live.count:
				live.set_sound(ref, resref)
		live.save()
	state["strings"] = {str(r): s for r, s in want.items()}
	save_state(sdir, state)
	print(f"Synced into {game}: {len(state['files'])} voice files, {len(want)} strings. "
	      f"Undo with --uninstall.")


if __name__ == "__main__":
	pause = "--pause" in sys.argv
	if pause:
		sys.argv.remove("--pause")  # set by the .bat when it relaunches elevated
	try:
		code = main()
	except BaseException:
		import traceback
		traceback.print_exc()
		code = 1
	if pause:
		try:
			input("Press Enter to close...")
		except EOFError:
			pass
	sys.exit(code)
